package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

// LoanRec struct // 01 LOAN-REC, 21 bytes
type LoanRec struct {
	LrAcct      string          // PIC X(6) @0 len=6
	LrPrincipal decimal.Decimal // PIC 9(7)V99 @6 len=9
	LrRate      decimal.Decimal // PIC 9(2)V99 @15 len=4
	LrYears     int64           // PIC 9(2) @19 len=2
}

// Standalone working-storage items
var WsEofFlag string          // PIC X len=1
var WsInterest decimal.Decimal // PIC 9(9)V99 len=11
var WsTotal decimal.Decimal    // PIC 9(11)V99 len=13
var WsCount int64             // PIC 9(5) len=5
var WsPrinEd string           // PIC Z,ZZZ,ZZ9.99 len=12
var WsIntEd string            // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsTotalEd string           // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var loanRec LoanRec

// file handling for LOAN-FILE
var loanFileLines []string
var loanFileIndex int

func InputDone() bool { return WsEofFlag == "Y" }

func intPow10(n int) int64 {
	var v int64 = 1
	for i := 0; i < n; i++ {
		v *= 10
	}
	return v
}

func storeDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	p := intDigits + int(scale)
	// factor = 10^scale
	factor := decimal.NewFromInt(1).Shift(scale)
	scaled := v.Mul(factor)
	// TRUNCATE toward zero to scale (remove extra fractional digits)
	scaled = scaled.Truncate(0)
	iv := scaled.IntPart()
	// modulo 10^p, keep sign
	mod := intPow10(p)
	sign := int64(1)
	if iv < 0 {
		sign = -1
		iv = -iv
	}
	iv = iv % mod
	iv *= sign
	return decimal.New(iv, -scale)
}

func formatEdited(v decimal.Decimal, pic string) string {
	// Determine intDigits and fracDigits from pic
	dotIdx := strings.Index(pic, ".")
	var intPartPic, fracPartPic string
	if dotIdx >= 0 {
		intPartPic = pic[:dotIdx]
		fracPartPic = pic[dotIdx+1:]
	} else {
		intPartPic = pic
		fracPartPic = ""
	}
	intDigits := 0
	for _, c := range intPartPic {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}
	fracDigits := 0
	for _, c := range fracPartPic {
		if c == 'Z' || c == '9' || c == '9' {
			fracDigits++
		}
	}

	// Absolute value for formatting (these fields are unsigned)
	av := v
	if av.IsNegative() {
		av = av.Neg()
	}

	// Truncate to fracDigits (editing does not round beyond)
	// But value already has correct scale; ensure truncation
	// Get integer and fractional parts
	// integerPart = trunc(av)
	intPartDec := av.Truncate(0)
	intPartAbs := intPartDec.IntPart()
	if intPartAbs < 0 {
		intPartAbs = -intPartAbs
	}
	// modulo for overflow (high-order digits dropped)
	if intDigits > 0 {
		mod := intPow10(intDigits)
		intPartAbs = intPartAbs % mod
	}
	integerStr := ""
	if intDigits > 0 {
		integerStr = fmt.Sprintf("%0*d", intDigits, intPartAbs)
	}

	var fracStr string
	if fracDigits > 0 {
		factor := decimal.NewFromInt(1).Shift(int32(fracDigits))
		// fractional part = av - intPart
		fracPartDec := av.Sub(decimal.NewFromInt(intPartDec.IntPart()))
		// handle negative? av positive so fine
		if fracPartDec.IsNegative() {
			fracPartDec = fracPartDec.Neg()
		}
		scaledFrac := fracPartDec.Mul(factor).Truncate(0)
		fracInt := scaledFrac.IntPart()
		if fracInt < 0 {
			fracInt = -fracInt
		}
		fracStr = fmt.Sprintf("%0*d", fracDigits, fracInt)
	}

	// Build result array
	result := []rune(pic)

	// Collect slot positions
	var intSlotPos []int
	var fracSlotPos []int
	for i, c := range pic {
		if dotIdx >= 0 {
			if i < dotIdx {
				if c == 'Z' || c == '9' {
					intSlotPos = append(intSlotPos, i)
				}
			} else if i > dotIdx {
				if c == 'Z' || c == '9' {
					fracSlotPos = append(fracSlotPos, i)
				}
			}
		} else {
			if c == 'Z' || c == '9' {
				intSlotPos = append(intSlotPos, i)
			}
		}
	}

	// Fill integer slots
	for idx, pos := range intSlotPos {
		if idx < len(integerStr) {
			result[pos] = rune(integerStr[idx])
		}
	}
	// Fill frac slots
	for idx, pos := range fracSlotPos {
		if idx < len(fracStr) {
			result[pos] = rune(fracStr[idx])
		}
	}

	// Z suppression for integer part
	suppress := true
	for _, pos := range intSlotPos {
		picChar := rune(pic[pos])
		digitChar := result[pos]
		if suppress {
			if digitChar != '0' {
				suppress = false
			} else {
				if picChar == 'Z' {
					result[pos] = ' '
				} else {
					suppress = false
				}
			}
		} else {
			// keep as is
		}
	}

	// Commas in integer part become spaces if all digit slots to left are spaces
	// Find commas
	for i, c := range pic {
		if c == ',' {
			if dotIdx >= 0 && i > dotIdx {
				continue
			}
			// check all integer slots with pos < i
			allSpaces := true
			hasLeft := false
			for _, p := range intSlotPos {
				if p < i {
					hasLeft = true
					if result[p] != ' ' {
						allSpaces = false
						break
					}
				}
			}
			if hasLeft && allSpaces {
				result[i] = ' '
			} else {
				// if no digit to left, shouldn't happen but keep comma?
				// For pic starting with Z, comma after first Z, if that Z suppressed,
				// then indeed should be space.
				// Already handled.
			}
		}
	}

	return string(result)
}

func parseDecimalField(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.New(0, 0)
	}
	// s contains digits only
	// Use decimal.NewFromString then shift? Easier: parse as integer then New with exponent
	// Remove leading spaces already, but keep digits
	// Could have non-digit? ignore?
	// Parse as int64
	// s may be up to 9 digits fits in int64
	var v int64
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			v = v*10 + int64(ch-'0')
		}
	}
	return decimal.New(v, -scale)
}

func parseIntField(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	var v int64
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			v = v*10 + int64(ch-'0')
		}
	}
	return v
}

func padRight(s string, n int) string {
	if len(s) >= n {
		if len(s) > n {
			return s[:n]
		}
		return s
	}
	return s + strings.Repeat(" ", n-len(s))
}

func loadLoanFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file doesn't exist, treat as empty
		loanFileLines = []string{}
		loanFileIndex = 0
		return
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	// Preserve spaces: Scanner's Split is ScanLines which keeps spaces
	// Increase buffer for long lines
	const maxCapacity = 10 * 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, maxCapacity)
	var lines []string
	for scanner.Scan() {
		txt := scanner.Text()
		// Remove trailing \r if present (Scanner already does, but for \r\n)
		// txt is without newline, keep spaces
		lines = append(lines, txt)
	}
	loanFileLines = lines
	loanFileIndex = 0
}

func formatWsCount() string {
	// PIC 9(5) zero-padded 5
	mod := intPow10(5)
	v := WsCount % mod
	if v < 0 {
		v = -v
	}
	return fmt.Sprintf("%05d", v)
}

// Paragraphs
func MainPara() {
	// Initialize working storage defaults (in case not set)
	WsEofFlag = "N"
	WsInterest = decimal.New(0, 0)
	WsTotal = decimal.New(0, 0)
	WsCount = 0

	loadLoanFile()
	ReadPara()
	for !InputDone() {
		ProcessPara()
	}
	// CLOSE LOAN-FILE is implicit (defer close already)
	SummaryPara()
}

func ReadPara() {
	if loanFileIndex < len(loanFileLines) {
		line := loanFileLines[loanFileIndex]
		loanFileIndex++
		// COBOL LINE SEQUENTIAL: pad with spaces to record length
		line = padRight(line, 21)
		// Parse fields
		loanRec.LrAcct = line[0:6]
		loanRec.LrPrincipal = parseDecimalField(line[6:15], 2)
		loanRec.LrRate = parseDecimalField(line[15:19], 2)
		loanRec.LrYears = parseIntField(line[19:21])
	} else {
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	// COMPUTE WS-INTEREST ROUNDED = LR-PRINCIPAL * LR-RATE * LR-YEARS / 100
	tmp := loanRec.LrPrincipal.Mul(loanRec.LrRate).Mul(decimal.NewFromInt(loanRec.LrYears)).Shift(-2)
	rounded := tmp.Round(2)
	WsInterest = storeDecimal(rounded, 9, 2)

	WsTotal = WsTotal.Add(WsInterest)
	WsTotal = storeDecimal(WsTotal, 11, 2)

	WsCount = WsCount + 1
	// keep low-order digits (PIC 9(5))
	WsCount = WsCount % intPow10(5)

	WsPrinEd = formatEdited(loanRec.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")

	// DISPLAY LR-ACCT " " WS-PRIN-ED " " WS-INT-ED
	// LR-ACCT is exactly 6 chars
	fmt.Printf("%s %s %s\n", loanRec.LrAcct, WsPrinEd, WsIntEd)

	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("RECORDS: %s\n", formatWsCount())
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

func main() {
	MainPara()
}
